/* ── THE ESTATE, IN THIS PRODUCT'S OWN MENU ───────────────────────────

   Vikram, 2026-09-05: "why are the drop down engines here NOT in the menus of
   gridatlas and pipelinenews". They are now, in both of this page's navs --
   the desktop sidebar and the RELEASES popover a phone opens -- because those
   are the two places a reader of THIS product already goes for a link.

   The forty-four nodes are not listed in this file. They are read from the
   graph the engine itself publishes, so a node added there appears here with
   no edit, and no second naming scheme can drift from it. Each row links to
   ?graph=engine-graph&focus=<label>, and the receiver matches on the node's
   own label -- exact first, then case-insensitively -- so the string in the
   link is the string the graph published.

   CROSS-ORIGIN, AND CHECKED RATHER THAN ASSUMED. This page is served from
   globalgrid2050.com and the genome is on ventusltd.github.io, so the fetch is
   cross-origin. GitHub Pages answers it with Access-Control-Allow-Origin: *
   -- verified against the live URL with a real Origin header before this was
   written, not assumed from the fact that it is public.

   IT IS ALSO NOT ALLOWED TO FAIL QUIETLY. A menu whose contents silently do
   not load is worse than a menu that does not offer them, because the reader
   cannot tell an empty estate from a broken one. So the list is fetched only
   when the reader asks for it, the failure prints its own reason in the menu
   where the list would have been, and the promise is cleared so the next tap
   is a real retry. The ENGINE GRAPH link above it is a plain anchor and works
   whether any of this runs or not.

   No MutationObserver, and nothing here observes the DOM: the toggle writes
   into one container it owns, once, on a click. */

const ENGINE_GRAPH_URL = "https://ventusltd.github.io/ventus-grid-engine/?graph=engine-graph";
const ENGINE_GENOME_URL = "https://ventusltd.github.io/ventus-grid-engine/genome/engine-graph.json";
/* Read order for the kinds the genome publishes today. It is a PREFERENCE, not
   a whitelist: any kind not named here is appended in the order it is met, so a
   new one is visible rather than silently dropped. */
const ENGINE_KIND_ORDER = ["canonical", "extract", "reference", "fragment"];

let engineGenomePromise = null;

function engineGenome() {
  if (!engineGenomePromise) {
    engineGenomePromise = fetch(ENGINE_GENOME_URL, { mode: "cors", cache: "no-store" })
      .then((response) => {
        if (!response.ok) throw new Error(`genome HTTP ${response.status}`);
        return response.json();
      })
      .then((genome) => {
        if (!Array.isArray(genome?.nodes) || !genome.nodes.length) {
          throw new Error("genome carries no nodes");
        }
        return genome;
      })
      .catch((error) => {
        // Cleared, so the next tap is a retry and not the same stale rejection.
        engineGenomePromise = null;
        throw error;
      });
  }
  return engineGenomePromise;
}

function engineFocusHref(label) {
  const url = new URL(ENGINE_GRAPH_URL);
  url.searchParams.set("focus", label);
  return url.href;
}

function renderEngineNodes(host, genome) {
  const groups = new Map();
  for (const node of genome.nodes) {
    const kind = String(node.type || "other");
    if (!groups.has(kind)) groups.set(kind, []);
    groups.get(kind).push(node);
  }
  const kinds = [
    ...ENGINE_KIND_ORDER.filter((kind) => groups.has(kind)),
    ...[...groups.keys()].filter((kind) => !ENGINE_KIND_ORDER.includes(kind)),
  ];
  host.replaceChildren();
  for (const kind of kinds) {
    const heading = document.createElement("b");
    heading.className = "engine-kind";
    heading.textContent = `${kind.toUpperCase()} · ${groups.get(kind).length}`;
    host.appendChild(heading);
    for (const node of groups.get(kind)) {
      const link = document.createElement("a");
      link.href = engineFocusHref(node.label);
      link.target = "_blank";
      link.rel = "noopener";
      link.textContent = node.label;
      if (node.reason) link.title = node.reason;
      host.appendChild(link);
    }
  }
}

function bindEstateLinks() {
  document.querySelectorAll("[data-engine-nodes]").forEach((button) => {
    const host = button.parentElement?.querySelector("[data-engine-node-list]");
    if (!host) return;
    button.addEventListener("click", async () => {
      if (!host.hidden) {
        host.hidden = true;
        button.setAttribute("aria-expanded", "false");
        return;
      }
      host.hidden = false;
      button.setAttribute("aria-expanded", "true");
      if (host.dataset.engineState === "ready") return;
      host.dataset.engineState = "loading";
      host.replaceChildren(Object.assign(document.createElement("i"),
        { className: "engine-note", textContent: "reading the engine genome…" }));
      try {
        const genome = await engineGenome();
        renderEngineNodes(host, genome);
        host.dataset.engineState = "ready";
        button.textContent = `ENGINE NODES · ${genome.nodes.length}`;
      } catch (error) {
        host.dataset.engineState = "failed";
        host.replaceChildren(Object.assign(document.createElement("i"),
          { className: "engine-note engine-failed",
            textContent: `ENGINE NODES UNAVAILABLE · ${error.message} · `
              + "the ENGINE GRAPH link above still opens the graph itself. Tap again to retry." }));
      }
    });
  });
}

