edits.to:
/* THE ESTATE LINKS IN THE NAV.

   The nav is a flex column and `.nav a` already styles every row in it, so the
   engine node rows inherit the product's own link shape and its 44px phone
   floor with no second rule. Only the toggle, the group headings and the
   failure line need anything, and `.engine-nodes[hidden]` needs saying out
   loud: `display:flex` on the container would otherwise beat the `hidden`
   attribute's UA rule and the list would be open before it was asked for. */

/* min-height, because this is the one row in the menu that is a <button> and
   not an <a>: at 393x852 it measured 37px against the 44px every link beside
   it meets, and a 37px control in a list of 44px controls is the one a thumb
   misses. */
.nav .engine-nodes-toggle {
  display: flex;
  align-items: center;
  min-height: 44px;
  padding: 12px 20px;
  background: none;
  border: 0;
  border-left: 3px solid transparent;
  color: var(--muted);
  font: bold 11px 'Courier New', monospace;
  text-align: left;
  cursor: pointer;
}

.nav .engine-nodes-toggle:hover,
.nav .engine-nodes-toggle[aria-expanded="true"] {
  color: var(--accent);
  background: #001414;
  border-left-color: var(--accent);
}

.nav .engine-nodes {
  display: flex;
  flex-direction: column;
  background: #04070a;
  border-left: 3px solid #37404a;
}

.nav .engine-nodes[hidden] {
  display: none;
}

.nav .engine-nodes a {
  padding: 10px 20px 10px 28px;
  font-weight: normal;
  font-size: 10px;
  text-transform: none;
}

.nav .engine-nodes .engine-kind {
  padding: 10px 20px 4px;
  color: #66717d;
  font: bold 9px 'Courier New', monospace;
  letter-spacing: .08em;
}

.nav .engine-nodes .engine-note {
  padding: 10px 20px;
  color: #aab4c0;
  font: normal 10px/1.55 'Courier New', monospace;
  font-style: normal;
}

.nav .engine-nodes .engine-failed {
  color: #ffcc00;
}

.study-link {
  text-decoration: none;
  display: inline-flex;
  align-items: center;
}

